CREATE TYPE public.app_role AS ENUM ('admin','agent','support');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated;
CREATE POLICY "Read own roles or admin team" ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.staff_invitations (email text PRIMARY KEY, role public.app_role NOT NULL, invited_by uuid, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.staff_invitations TO authenticated;
GRANT ALL ON public.staff_invitations TO service_role;
ALTER TABLE public.staff_invitations ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins manage invitations" ON public.staff_invitations FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.redeem_staff_invitation() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mail text; BEGIN SELECT lower(email) INTO mail FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF mail IS NULL THEN RETURN; END IF; INSERT INTO public.user_roles(user_id,role) SELECT auth.uid(),role FROM public.staff_invitations WHERE email=mail ON CONFLICT DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.redeem_staff_invitation() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.redeem_staff_invitation() TO authenticated;
CREATE TABLE public.site_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), trading_enabled boolean NOT NULL DEFAULT true, robot_enabled boolean NOT NULL DEFAULT true, deposits_enabled boolean NOT NULL DEFAULT true, withdrawals_enabled boolean NOT NULL DEFAULT true, announcement text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_settings TO anon;
GRANT SELECT,INSERT,UPDATE ON public.site_settings TO authenticated;
GRANT ALL ON public.site_settings TO service_role;
ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public reads safe settings" ON public.site_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admins create settings" ON public.site_settings FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins update settings" ON public.site_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
INSERT INTO public.site_settings (id) VALUES (true) ON CONFLICT (id) DO NOTHING;
CREATE TABLE public.support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, subject text NOT NULL, message text NOT NULL, reply text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX support_tickets_user_created_idx ON public.support_tickets(user_id, created_at DESC);
GRANT SELECT,INSERT,UPDATE ON public.support_tickets TO authenticated;
GRANT ALL ON public.support_tickets TO service_role;
ALTER TABLE public.support_tickets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner and support read tickets" ON public.support_tickets FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'support'));
CREATE POLICY "Users create own tickets" ON public.support_tickets FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='open' AND reply='');
CREATE POLICY "Support responds" ON public.support_tickets FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'support')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'support'));
CREATE TABLE public.admin_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL REFERENCES auth.users(id), action text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX admin_audit_created_at_idx ON public.admin_audit(created_at DESC);
GRANT SELECT,INSERT ON public.admin_audit TO authenticated;
GRANT ALL ON public.admin_audit TO service_role;
ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins read audit" ON public.admin_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY "Staff record own actions" ON public.admin_audit FOR INSERT TO authenticated WITH CHECK(actor_id=auth.uid() AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'support')));
CREATE POLICY "Staff read clients" ON public.profiles FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'agent'));
CREATE POLICY "Staff read practice activity" ON public.practice_accounts FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'agent'));
CREATE FUNCTION public.set_staff_role(target_user uuid,new_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF target_user=auth.uid() THEN RAISE EXCEPTION 'Cannot change your own role'; END IF; DELETE FROM public.user_roles WHERE user_id=target_user; INSERT INTO public.user_roles(user_id,role) VALUES(target_user,new_role); END $$;
REVOKE ALL ON FUNCTION public.set_staff_role(uuid,public.app_role) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.set_staff_role(uuid,public.app_role) TO authenticated;
CREATE FUNCTION public.revoke_staff(target_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') OR target_user=auth.uid() THEN RAISE EXCEPTION 'Forbidden'; END IF; DELETE FROM public.staff_invitations WHERE email IN (SELECT lower(email) FROM auth.users WHERE id=target_user); DELETE FROM public.user_roles WHERE user_id=target_user; END $$;
REVOKE ALL ON FUNCTION public.revoke_staff(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.revoke_staff(uuid) TO authenticated;
